import {buildIndex} from './document-engine.mjs';
export const MEMORY_TTL=7*86400000;
export function validMemory(records,now=Date.now()){return records.filter(r=>r&&typeof r.id==='string'&&Array.isArray(r.pages)&&Number.isFinite(r.savedAt)&&now-r.savedAt>=0&&now-r.savedAt<MEMORY_TTL&&/^https:\/\/(tr|en)\.wikipedia\.org\/wiki\//.test(r.url||''));}
export function memoryRecords(results,retrievedAt,now=Date.now()){const fetched=Date.parse(retrievedAt);return results.filter(r=>typeof r.text==='string'&&typeof r.name==='string'&&/^https:\/\/(tr|en)\.wikipedia\.org\/wiki\//.test(r.url||'')).slice(0,3).map(r=>({id:r.url,name:r.name.slice(0,200),url:r.url,language:r.language,licenseUrl:'https://creativecommons.org/licenses/by-sa/4.0/',savedAt:Number.isFinite(fetched)?Math.min(now,fetched):now,pages:[{page:null,text:r.text.slice(0,1400)}]}));}
export function recalledSources(question,records,now=Date.now()){const fresh=validMemory(records,now),hits=buildIndex(fresh).search(question);return hits.map(hit=>{const record=fresh.find(r=>r.id===hit.id);return {...hit,url:record.url,language:record.language,licenseUrl:record.licenseUrl,savedAt:record.savedAt};});}
export function generalMessages(question){return [{role:'system',content:'Türkçe yardımcı bir asistansın. Yazı yazma, kod örneği, açıklama ve akıl yürütme isteklerine yardımcı ol. Bu yanıtta doğrulanmış internet kaynağın yok. Kaynak veya bağlantı uydurma, internette araştırdığını söyleme. Emin olmadığın olguları kesinmiş gibi sunma; bilgi yetmiyorsa belirt veya açıklayıcı soru sor. Güncel bilgi, fiyat, kişi görevi veya tıbbi/hukuki karar için doğrulama gerektiğini belirt. Özel kullanıcı verisi isteme. Fotoğraftan kimyasal kimlik veya saflık tespit ettiğini iddia etme.'},{role:'user',content:question}];}

export function needsFreshSearch(question){return /bugün|güncel|şimdi|son durum|fiyat|hava durumu|current|today|latest/iu.test(question);}
